def rmse(predictions: np.array, actuals: np.array) -> float:
    return np.sqrt(np.mean((predictions - actuals) ** 2))

def brier_score(probabilities: dict, outcome: str) -> float:
    """For categorical outcomes (cut/hold/hike)."""
    return sum((probabilities[cat] - (1 if cat == outcome else 0))**2 for cat in probabilities)

def interval_coverage(intervals: list[tuple], actuals: list) -> float:
    """Fraction of actuals within predicted intervals."""
    covered = sum(lower <= actual <= upper for (lower, upper), actual in zip(intervals, actuals))
    return covered / len(actuals)

def calibration_curve(probabilities: np.array, outcomes: np.array, n_bins: int = 10):
    """Bin predictions and compute empirical frequencies."""
    # For plotting: predicted prob vs actual frequency
    from sklearn.calibration import calibration_curve
    return calibration_curve(outcomes, probabilities, n_bins=n_bins)
