import shap

class SHAPExplainer:
    def __init__(self, model):
        # Use TreeExplainer for LightGBM
        self.explainer = shap.TreeExplainer(model)

    def explain_prediction(self, X: pd.DataFrame) -> dict:
        """Return SHAP values for a single prediction."""
        shap_values = self.explainer.shap_values(X)

        # Convert to dict for JSON storage
        if X.shape[0] == 1:
            feature_contributions = {feat: float(val) for feat, val in zip(X.columns, shap_values[0])}
        else:
            feature_contributions = {feat: shap_values[:, i].tolist() for i, feat in enumerate(X.columns)}

        return {
            'shap_values': feature_contributions,
            'base_value': float(self.explainer.expected_value)
        }
