from sklearn.calibration import CalibratedClassifierCV
from sklearn.isotonic import IsotonicRegression

class IntervalCalibrator:
    """Conformal prediction for calibrated intervals."""
    def __init__(self, coverage: float = 0.8):
        self.coverage = coverage
        self.quantile = None

    def fit(self, residuals: np.array):
        """Fit on validation residuals."""
        self.quantile = np.quantile(np.abs(residuals), self.coverage)

    def predict_interval(self, point_prediction: float) -> tuple:
        return (point_prediction - self.quantile, point_prediction + self.quantile)

class ProbabilityCalibrator:
    """Isotonic/Platt scaling for FOMC probabilities."""
    def __init__(self, method: str = 'isotonic'):
        self.method = method
        self.calibrator = IsotonicRegression(out_of_bounds='clip') if method == 'isotonic' else None

    def fit(self, predicted_probs: np.array, actual_outcomes: np.array):
        self.calibrator.fit(predicted_probs, actual_outcomes)

    def calibrate(self, probs: np.array) -> np.array:
        return self.calibrator.predict(probs)
